import { readdirSync, readFileSync, statSync } from 'node:fs'
import { basename, join, relative, sep } from 'node:path'
import { createChecker } from 'vue-component-meta'
import { classNames, customPropertyDeclarations, propertyNames, stripNoise } from './css-scan'

const HEADER =
  '<!-- GENERATED by scripts/gen-api.ts - do not edit. A diff here is a public API change. -->'

// Code-unit order, so the output never depends on locale or readdir order.
const byCodeUnit = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0)
const sorted = (values: Iterable<string>) => [...new Set(values)].sort(byCodeUnit)
const list = (values: string[]) =>
  values.length ? values.map((v) => `- \`${v}\``).join('\n') : '- none'
const inline = (values: string[]) =>
  values.length ? values.map((v) => `\`${v}\``).join(', ') : 'none'
const posix = (path: string) => path.split(sep).join('/')

function files(dir: string, ext: string): string[] {
  return readdirSync(dir, { recursive: true })
    .map(String)
    .filter((file) => file.endsWith(ext))
    .map((file) => join(dir, file))
    .filter((file) => statSync(file).isFile())
    .sort(byCodeUnit)
}

// Runtime (non-type) names exported from vue/index.ts.
export function barrelExports(root: string): string[] {
  const source = readFileSync(join(root, 'vue/index.ts'), 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/.*$/gm, '')
  if (/^export\s+\*\s+(?:as\s+\w+\s+)?from/m.test(source)) {
    throw new Error('vue/index.ts: `export * from` cannot be listed statically; name the exports')
  }
  const names: string[] = []
  for (const m of source.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of m[1]!.split(',')) {
      const spec = part.trim()
      if (!spec || spec.startsWith('type ')) continue
      names.push(
        spec
          .split(/\s+as\s+/)
          .pop()!
          .trim()
      )
    }
  }
  for (const m of source.matchAll(
    /^export\s+(?:async\s+)?(?:const|let|var|function\*?|class)\s+(\w+)/gm
  )) {
    names.push(m[1]!)
  }
  return sorted(names)
}

export function autoImports(root: string): string[] {
  const source = readFileSync(join(root, 'nuxt/module.ts'), 'utf8')
  const block = /const AUTO_IMPORTS = \[([\s\S]*?)\] as const/.exec(source)?.[1] ?? ''
  return [...block.matchAll(/'(\w+)'/g)].map((m) => m[1]!)
}

// Absolute paths can leak into printed types as import("/abs/path").Name; keep them repo-relative.
function scrub(root: string, text: string): string {
  return text.split(root).join('<root>').split(posix(root)).join('<root>').replace(/\s+/g, ' ')
}

function componentSection(root: string): string {
  const checker = createChecker(join(root, 'tsconfig.json'), {
    schema: false,
    printer: { newLine: 1 }
  })
  const dir = join(root, 'vue/components')
  return files(dir, '.vue')
    .map((file) => {
      const name = basename(file, '.vue')
      const meta = checker.getComponentMeta(file)
      const cell = (text: string) => scrub(root, text).replace(/\|/g, '\\|')
      const props = meta.props
        .filter((p) => !p.global)
        .sort((a, b) => byCodeUnit(a.name, b.name))
        .map(
          (p) =>
            `| \`${p.name}\` | \`${cell(p.type)}\` | ${p.required ? 'yes' : 'no'} | ${
              p.default === undefined ? '' : `\`${cell(p.default)}\``
            } |`
        )
      const slots = sorted(meta.slots.map((s) => s.name))
      const events = sorted(meta.events.map((e) => e.name))
      const propNames = new Set(meta.props.map((p) => p.name))
      const exposed = sorted(
        meta.exposed
          .map((e) => e.name)
          .filter((n) => !propNames.has(n) && !n.startsWith('$') && !/^on[A-Z]/.test(n))
      )
      return [
        `### ${name}`,
        '',
        props.length
          ? ['| prop | type | required | default |', '| --- | --- | --- | --- |', ...props].join(
              '\n'
            )
          : 'No props.',
        '',
        `Slots: ${inline(slots)}`,
        `Events: ${inline(events)}`,
        `Exposed: ${inline(exposed)}`
      ].join('\n')
    })
    .join('\n\n')
}

export function renderApi(root: string): string {
  const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as {
    exports: Record<string, unknown>
  }
  const css = files(join(root, 'css'), '.css').filter((f) => basename(f) !== 'fonts.css')
  const allCss = css.map((f) => readFileSync(f, 'utf8')).join('\n')
  const tokenDecls = new Set(
    customPropertyDeclarations(readFileSync(join(root, 'css/tokens.css'), 'utf8'))
  )
  const registered = new Set(propertyNames(allCss))
  const used = [...stripNoise(allCss).matchAll(/var\(\s*(--bl-[\w-]+)/g)].map((m) => m[1]!)
  const hooks = sorted(used.filter((name) => !tokenDecls.has(name) && !registered.has(name)))
  const theme = [
    ...readFileSync(join(root, 'tailwind/theme.css'), 'utf8').matchAll(/^\s+(--[\w-]+):/gm)
  ].map((m) => m[1]!)
  const dist = files(join(root, 'dist'), '').map((f) => posix(relative(root, f)))

  return [
    HEADER,
    '',
    '# Benchlight public API',
    '',
    '## Package exports',
    list(sorted(Object.keys(pkg.exports))),
    '',
    '## dist files',
    list(sorted(dist)),
    '',
    '## benchlight/vue exports',
    list(barrelExports(root)),
    '',
    '## Nuxt auto-imports',
    list(sorted(autoImports(root))),
    '',
    '## Components',
    '',
    componentSection(root),
    '',
    '## CSS classes',
    list(sorted(classNames(allCss).filter((c) => c.startsWith('bl-')))),
    '',
    '## CSS hooks (custom properties a consumer may set)',
    list(hooks),
    '',
    '## Tailwind theme variables',
    list(sorted(theme)),
    ''
  ].join('\n')
}
